CREATE DATABASE IF NOT EXISTS sante CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE sante;

CREATE TABLE users (id VARCHAR(30) PRIMARY KEY, name VARCHAR(150), email VARCHAR(190) NOT NULL UNIQUE, emailVerified DATETIME NULL, image VARCHAR(255), role VARCHAR(30) NOT NULL DEFAULT 'patient', password VARCHAR(255), mustChangePassword BOOLEAN NOT NULL DEFAULT TRUE, failedLoginAttempts INT NOT NULL DEFAULT 0, lockedUntil DATETIME NULL, createdAt DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, updatedAt DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, INDEX idx_users_role(role));
CREATE TABLE sessions (id VARCHAR(30) PRIMARY KEY, sessionToken VARCHAR(255) NOT NULL UNIQUE, userId VARCHAR(30) NOT NULL, expires DATETIME NOT NULL, FOREIGN KEY (userId) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE accounts (id VARCHAR(30) PRIMARY KEY, userId VARCHAR(30) NOT NULL, type VARCHAR(50) NOT NULL, provider VARCHAR(100) NOT NULL, providerAccountId VARCHAR(190) NOT NULL, refresh_token TEXT, access_token TEXT, expires_at INT, token_type VARCHAR(50), scope TEXT, id_token TEXT, session_state VARCHAR(255), UNIQUE KEY uq_provider_account(provider, providerAccountId), FOREIGN KEY (userId) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE verification_tokens (identifier VARCHAR(190) NOT NULL, token VARCHAR(255) NOT NULL UNIQUE, expires DATETIME NOT NULL, UNIQUE KEY uq_identifier_token(identifier, token));
CREATE TABLE hopitaux (id INT AUTO_INCREMENT PRIMARY KEY, nom VARCHAR(150) NOT NULL, adresse VARCHAR(255) NOT NULL, telephone VARCHAR(40) NOT NULL, email VARCHAR(190) NOT NULL, lits INT NOT NULL DEFAULT 0, litsOccupes INT NOT NULL DEFAULT 0, services TEXT, latitude DECIMAL(10,7), longitude DECIMAL(10,7), createdAt DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE medecins (id INT AUTO_INCREMENT PRIMARY KEY, userId VARCHAR(30) NOT NULL UNIQUE, specialite VARCHAR(120) NOT NULL, licence VARCHAR(100) NOT NULL, hopitalId INT NOT NULL, createdAt DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (userId) REFERENCES users(id) ON DELETE CASCADE, FOREIGN KEY (hopitalId) REFERENCES hopitaux(id) ON DELETE CASCADE, INDEX idx_medecins_specialite(specialite));
CREATE TABLE patients (id INT AUTO_INCREMENT PRIMARY KEY, userId VARCHAR(30) NOT NULL UNIQUE, numero_national VARCHAR(100) NOT NULL UNIQUE, nom VARCHAR(100) NOT NULL, prenom VARCHAR(100) NOT NULL, date_naissance DATE NOT NULL, lieu_naissance VARCHAR(150) NOT NULL, sexe VARCHAR(30) NOT NULL, situation_matrimoniale VARCHAR(50) NOT NULL, createdAt DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE consultations (id INT AUTO_INCREMENT PRIMARY KEY, medecinId INT NOT NULL, patientId INT NOT NULL, dateConsultation DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, motif TEXT NOT NULL, diagnostique TEXT, notes TEXT, prix DECIMAL(10,2), createdAt DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (medecinId) REFERENCES medecins(id) ON DELETE CASCADE, FOREIGN KEY (patientId) REFERENCES patients(id) ON DELETE CASCADE, INDEX idx_consultations_date(dateConsultation));
CREATE TABLE examens_medicaux (id INT AUTO_INCREMENT PRIMARY KEY, consultationId INT NOT NULL, typeExamen VARCHAR(150) NOT NULL, resultat TEXT, dateExamen DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, statut VARCHAR(30) NOT NULL DEFAULT 'demandé', prix DECIMAL(10,2), createdAt DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (consultationId) REFERENCES consultations(id) ON DELETE CASCADE);
CREATE TABLE prescriptions_medicales (id INT AUTO_INCREMENT PRIMARY KEY, consultationId INT NOT NULL, datePrescription DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, posologie TEXT NOT NULL, dureeTraitement VARCHAR(100) NOT NULL, quantite VARCHAR(100) NOT NULL, instruction TEXT, statut VARCHAR(30) NOT NULL DEFAULT 'active', createdAt DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (consultationId) REFERENCES consultations(id) ON DELETE CASCADE);
CREATE TABLE medicaments (id INT AUTO_INCREMENT PRIMARY KEY, nomCommercial VARCHAR(150) NOT NULL, nomGenerique VARCHAR(150) NOT NULL, dosage VARCHAR(80) NOT NULL, formePharmaceutique VARCHAR(100) NOT NULL, voieAdministration VARCHAR(100) NOT NULL, prix DECIMAL(10,2), description TEXT, quantiteEnStock INT NOT NULL DEFAULT 0);
CREATE TABLE prescription_medicaments (prescriptionId INT NOT NULL, medicamentId INT NOT NULL, PRIMARY KEY (prescriptionId, medicamentId), FOREIGN KEY (prescriptionId) REFERENCES prescriptions_medicales(id) ON DELETE CASCADE, FOREIGN KEY (medicamentId) REFERENCES medicaments(id) ON DELETE CASCADE);
CREATE TABLE rendez_vous (id INT AUTO_INCREMENT PRIMARY KEY, patientId INT NOT NULL, medecinId INT NOT NULL, date DATETIME NOT NULL, statut VARCHAR(30) NOT NULL DEFAULT 'Planifié', motif TEXT, createdAt DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, updatedAt DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY (patientId) REFERENCES patients(id) ON DELETE CASCADE, FOREIGN KEY (medecinId) REFERENCES medecins(id) ON DELETE CASCADE);
CREATE TABLE alertes_sanitaires (id INT AUTO_INCREMENT PRIMARY KEY, titre VARCHAR(190) NOT NULL, description TEXT NOT NULL, niveau VARCHAR(30) NOT NULL DEFAULT 'Information', statut VARCHAR(30) NOT NULL DEFAULT 'Active', dateDebut DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, dateFin DATETIME NULL, createdAt DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE laboratoires (id INT AUTO_INCREMENT PRIMARY KEY, nom VARCHAR(150) NOT NULL, adresse VARCHAR(255), telephone VARCHAR(40), email VARCHAR(190), actif BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE resultats_laboratoire (id INT AUTO_INCREMENT PRIMARY KEY, examenId INT NOT NULL, laboratoireId INT NOT NULL, referenceExterne VARCHAR(100), resultat TEXT, dateReception DATETIME NULL, statut VARCHAR(30) NOT NULL DEFAULT 'En attente', FOREIGN KEY (examenId) REFERENCES examens_medicaux(id) ON DELETE CASCADE, FOREIGN KEY (laboratoireId) REFERENCES laboratoires(id) ON DELETE CASCADE);
CREATE TABLE delivrances (id INT AUTO_INCREMENT PRIMARY KEY, prescriptionId INT NOT NULL, medicamentId INT NOT NULL, quantite INT NOT NULL, dateDelivrance DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, delivrePar VARCHAR(30), FOREIGN KEY (prescriptionId) REFERENCES prescriptions_medicales(id) ON DELETE CASCADE, FOREIGN KEY (medicamentId) REFERENCES medicaments(id) ON DELETE CASCADE, FOREIGN KEY (delivrePar) REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE interactions_medicamenteuses (id INT AUTO_INCREMENT PRIMARY KEY, medicamentId INT NOT NULL, medicamentAssocieId INT NOT NULL, niveau VARCHAR(30) NOT NULL DEFAULT 'Vigilance', description TEXT NOT NULL, FOREIGN KEY (medicamentId) REFERENCES medicaments(id) ON DELETE CASCADE, FOREIGN KEY (medicamentAssocieId) REFERENCES medicaments(id) ON DELETE CASCADE, UNIQUE KEY uq_interaction(medicamentId, medicamentAssocieId));

